     6	/**
     7	 * cos(2π·i/64)·1024 rounded, for the first quarter turn (i = 0…16). Written out as data so that no floating-point
     8	 * transcendental function runs in the simulation; the other three quarters follow by symmetry.
     9	 */
    10	const QUARTER_COSINES: readonly number[] = [1024, 1019, 1004, 980, 946, 903, 851, 792, 724, 650, 569, 483, 392, 297, 200, 100, 0];
    11	
    12	const QUARTER = HEADING_COUNT / 4;
    13	
    14	function cosine(heading: number): number {
    15	  const turn = normalizeHeading(heading);
    16	  if (turn <= QUARTER) return QUARTER_COSINES[turn]!;
    17	  // Subtracting from 0 rather than negating keeps the table free of -0.
    18	  if (turn <= 2 * QUARTER) return 0 - QUARTER_COSINES[2 * QUARTER - turn]!;
    19	  if (turn <= 3 * QUARTER) return 0 - QUARTER_COSINES[turn - 2 * QUARTER]!;
    20	  return QUARTER_COSINES[HEADING_COUNT - turn]!;
    21	}
