     4	/** Whether `viewer` sees `target`: within the sight radius, centre to centre, compared in integer squares (§3). */
     5	export function canSee(config: SimulationConfig, viewer: ShipState, target: ShipState): boolean {
     6	  if (viewer.id === target.id) return true;
     7	  const dx = target.x - viewer.x;
     8	  const dy = target.y - viewer.y;
     9	  return dx * dx + dy * dy <= config.sightRadius * config.sightRadius;
    10	}
