    14	 * The server sends a client these ships and no others.
    15	 */
    16	export function visibleShipIds(config: SimulationConfig, state: MatchState, viewerId: string): Set<string> {
    17	  const viewer = state.ships.find((ship) => ship.id === viewerId);
    18	  const visible = new Set<string>();
    19	  if (viewer === undefined) return visible;
    20	  for (const ship of state.ships) if (canSee(config, viewer, ship)) visible.add(ship.id);
    21	  return visible;
    22	}

