    88	export function validateSeaMap(map: SeaMapDefinition, tuning: ShipTuning, rules: SeaMapRules = sliceSeaRules): ValidationResult<SeaMapReport> {
    89	  const issues: string[] = [];
    90	  const { islands, docks, spawnSlots } = map;
    91	  const tileCentre = Math.floor(map.subUnitsPerTile / 2);
    92	
    93	  if (tuning.hullHalfSize >= tileCentre) issues.push(`ship hull half-size ${tuning.hullHalfSize} does not fit inside one tile`);
    94	  if (SIGHT_RADIUS_TILES <= ENGAGEMENT_RANGE_TILES) issues.push("the sight radius must be larger than the engagement range");
    95	
    96	  if (islands.length !== rules.islands) issues.push(`${islands.length} islands, not ${rules.islands}`);
    97	  islands.forEach((island, index) => {
    98	    if (island.widthTiles > MAX_ISLAND_SIDE_TILES || island.heightTiles > MAX_ISLAND_SIDE_TILES) {
    99	      issues.push(`${island.name}: ${island.widthTiles} × ${island.heightTiles} tiles is not a small island`);
   100	    }
   101	    if (island.tileX < 0 || island.tileY < 0 || island.tileX + island.widthTiles > map.widthTiles || island.tileY + island.heightTiles > map.heightTiles) {
   102	      issues.push(`${island.name}: outside the map`);
   103	    }
   104	    for (const other of islands.slice(index + 1)) {
   105	      const apart =
   106	        island.tileX + island.widthTiles <= other.tileX ||
   107	        other.tileX + other.widthTiles <= island.tileX ||
   108	        island.tileY + island.heightTiles <= other.tileY ||
   109	        other.tileY + other.heightTiles <= island.tileY;
   110	      if (!apart) issues.push(`${island.name} and ${other.name} overlap`);
   111	    }
   112	    if (!docks.some((dock) => dock.island === index)) issues.push(`${island.name}: no dock`);
   113	  });
   114	
   115	  let landTiles = 0;
   116	  let shoalTiles = 0;
   117	  for (let tileY = 0; tileY < map.heightTiles; tileY++) {
   118	    for (let tileX = 0; tileX < map.widthTiles; tileX++) {
   119	      const kind = terrainAt(map, tileX, tileY);
   120	      if (kind === Terrain.Shoal) shoalTiles++;
   121	      if (kind !== Terrain.Land) continue;
   122	      landTiles++;
   123	      const owners = islands.filter((island) => insideIsland(island, tileX, tileY)).length;
   124	      if (owners !== 1) issues.push(`land at ${tileX},${tileY} lies in ${owners} island rectangles, not one`);
   125	    }
   126	  }
   127	  if (landTiles === 0) issues.push("no land");
   128	  if (shoalTiles === 0) issues.push("no shoals");
   129	
   130	  const neighbours = (tileX: number, tileY: number) => [
   131	    [tileX + 1, tileY],
   132	    [tileX - 1, tileY],
   133	    [tileX, tileY + 1],
   134	    [tileX, tileY - 1],
   135	  ] as const;
   136	  for (const dock of docks) {
   137	    const where = `dock at ${dock.tileX},${dock.tileY}`;
   138	    const island = islands[dock.island];
   139	    if (island === undefined) {
   140	      issues.push(`${where}: outside every island rectangle`);
   141	      continue;
   142	    }
   143	    const touches = (kind: Terrain) =>
   144	      neighbours(dock.tileX, dock.tileY).some(([x, y]) => terrainAt(map, x, y) === kind && (kind !== Terrain.Land || insideIsland(island, x, y)));
   145	    if (!touches(Terrain.Land)) issues.push(`${where}: not beside ${island.name}'s land`);
   146	    if (!touches(Terrain.Sea)) issues.push(`${where}: no open sea beside it`);
   147	  }
   148	
   149	  if (spawnSlots.length !== rules.spawnSlots) issues.push(`${spawnSlots.length} spawn slots, not ${rules.spawnSlots}`);
   150	  const archipelago = boundsOf(islands);
   151	  spawnSlots.forEach((slot, index) => {
   152	    const where = `spawn slot ${index} at ${slot.tileX},${slot.tileY}`;
   153	    if (terrainAt(map, slot.tileX, slot.tileY) !== Terrain.Sea) issues.push(`${where}: not on open sea`);
   154	    if (
   155	      archipelago !== undefined &&
   156	      slot.tileX >= archipelago.minX &&
   157	      slot.tileX <= archipelago.maxX &&
   158	      slot.tileY >= archipelago.minY &&
   159	      slot.tileY <= archipelago.maxY
   160	    ) {
   161	      issues.push(`${where}: inside the archipelago, not on the outer sea`);
   162	    }
   163	    spawnSlots.slice(index + 1).forEach((other, offset) => {
   164	      const dx = other.tileX - slot.tileX;
   165	      const dy = other.tileY - slot.tileY;
   166	      if (dx * dx + dy * dy <= ENGAGEMENT_RANGE_TILES * ENGAGEMENT_RANGE_TILES) {
   167	        issues.push(`${where}: within engagement range of slot ${index + 1 + offset}`);
   168	      }
   169	    });
   170	  });
   171	  if (issues.length > 0) return { ok: false, issues };
   172	
   173	  // Travel: one shortest-path search from every dock and spawn slot.
   174	  const points: PointOfInterest[] = [
   175	    ...docks.map((dock) => ({ label: `${islands[dock.island]!.name} ${dock.side} dock`, tileX: dock.tileX, tileY: dock.tileY })),
   176	    ...spawnSlots.map((slot, index) => ({ label: `spawn slot ${index}`, tileX: slot.tileX, tileY: slot.tileY })),
   177	  ];
   178	  const costs = points.map((point) => seaPathCosts(map, point.tileX, point.tileY));
   179	  const between = (from: number, to: number) => costs[from]![points[to]!.tileY * map.widthTiles + points[to]!.tileX]!;
   180	
   181	  const origin = docks.length;
   182	  points.forEach((point, index) => {
   183	    if (between(origin, index) === UNREACHABLE) issues.push(`${point.label} at ${point.tileX},${point.tileY}: not reachable by sea from spawn slot 0`);
   184	  });
   185	  if (issues.length > 0) return { ok: false, issues };
   186	
   187	  const nearestIsland = islands.map((island, index) => {
   188	    let best = { nearest: "", cost: UNREACHABLE };
   189	    docks.forEach((from, fromIndex) => {
   190	      if (from.island !== index) return;
   191	      docks.forEach((to, toIndex) => {
   192	        if (to.island === index) return;
   193	        const cost = between(fromIndex, toIndex);
   194	        if (cost < best.cost) best = { nearest: islands[to.island]!.name, cost };
   195	      });
   196	    });
   197	    return { island: island.name, nearest: best.nearest, seconds: travelSeconds(best.cost, tuning) };
   198	  });
   199	  for (const entry of nearestIsland) {
   200	    if (entry.seconds < travelTargets.neighbourIslandMinSeconds || entry.seconds > travelTargets.neighbourIslandMaxSeconds) {
   201	      issues.push(
   202	        `${entry.island}: its nearest island, ${entry.nearest}, is ${entry.seconds} s away, outside ${travelTargets.neighbourIslandMinSeconds}–${travelTargets.neighbourIslandMaxSeconds} s`,
   203	      );
   204	    }
   205	  }
   206	
   207	  let longest = { from: "", to: "", cost: 0 };
   208	  points.forEach((from, fromIndex) => {
   209	    points.forEach((to, toIndex) => {
   210	      const cost = between(fromIndex, toIndex);
   211	      if (cost > longest.cost) longest = { from: from.label, to: to.label, cost };
   212	    });
   213	  });
   214	  const longestCrossing = { from: longest.from, to: longest.to, seconds: travelSeconds(longest.cost, tuning) };
   215	  if (longestCrossing.seconds > travelTargets.longestCrossingMaxSeconds) {
   216	    issues.push(`the crossing from ${longest.from} to ${longest.to} takes ${longestCrossing.seconds} s, over ${travelTargets.longestCrossingMaxSeconds} s`);
   217	  }
   218	
   219	  const firstDock = spawnSlots.map((_, slot) => {
   220	    let best = { dock: "", cost: UNREACHABLE };
   221	    docks.forEach((_, dockIndex) => {
   222	      const cost = between(origin + slot, dockIndex);
   223	      if (cost < best.cost) best = { dock: points[dockIndex]!.label, cost };
   224	    });
   225	    return { slot, dock: best.dock, seconds: travelSeconds(best.cost, tuning) };
   226	  });
   227	  for (const entry of firstDock) {
   228	    if (entry.seconds > travelTargets.firstDockMaxSeconds) {
   229	      issues.push(`spawn slot ${entry.slot}: the nearest dock is ${entry.seconds} s away, over ${travelTargets.firstDockMaxSeconds} s`);
   230	    }
   231	  }
   232	
   233	  return issues.length > 0 ? { ok: false, issues } : { ok: true, value: { nearestIsland, longestCrossing, firstDock } };
   234	}
   235	
   236	function boundsOf(islands: SeaMapDefinition["islands"]) {
   237	  if (islands.length === 0) return undefined;
   238	  return {
   239	    minX: Math.min(...islands.map((island) => island.tileX)),
   240	    minY: Math.min(...islands.map((island) => island.tileY)),
   241	    maxX: Math.max(...islands.map((island) => island.tileX + island.widthTiles - 1)),
   242	    maxY: Math.max(...islands.map((island) => island.tileY + island.heightTiles - 1)),
   243	  };
   244	}
   245	
   246	/** A binary min-heap of (cost, index) pairs for the path search. */
   247	class MinHeap {
   248	  private readonly costs: number[] = [];
   249	  private readonly indexes: number[] = [];
   250	
   251	  get size(): number {
   252	    return this.costs.length;
   253	  }
   254	
   255	  push(cost: number, index: number): void {
   256	    this.costs.push(cost);
   257	    this.indexes.push(index);
   258	    let child = this.costs.length - 1;
   259	    while (child > 0) {
   260	      const parent = (child - 1) >> 1;
   261	      if (this.costs[parent]! <= cost) break;
   262	      this.swap(child, parent);
   263	      child = parent;
   264	    }
   265	  }
   266	
   267	  pop(): [number, number] {
   268	    const top: [number, number] = [this.costs[0]!, this.indexes[0]!];
   269	    const lastCost = this.costs.pop()!;
   270	    const lastIndex = this.indexes.pop()!;
   271	    if (this.costs.length > 0) {
   272	      this.costs[0] = lastCost;
   273	      this.indexes[0] = lastIndex;
   274	      let parent = 0;
   275	      for (;;) {
   276	        const left = 2 * parent + 1;
   277	        const right = left + 1;
   278	        let smallest = parent;
   279	        if (left < this.costs.length && this.costs[left]! < this.costs[smallest]!) smallest = left;
   280	        if (right < this.costs.length && this.costs[right]! < this.costs[smallest]!) smallest = right;
   281	        if (smallest === parent) break;
   282	        this.swap(parent, smallest);
   283	        parent = smallest;
   284	      }
   285	    }
   286	    return top;
   287	  }
   288	
   289	  private swap(a: number, b: number): void {
   290	    [this.costs[a], this.costs[b]] = [this.costs[b]!, this.costs[a]!];
   291	    [this.indexes[a], this.indexes[b]] = [this.indexes[b]!, this.indexes[a]!];
   292	  }
   293	}

