 64	  for (const point of visited) expect(isNavigable(seaMap, Math.floor(point.x / TILE), Math.floor(point.y / TILE))).toBe(true);
 65	  expect(visited.some((point) => Math.floor(point.x / TILE) > shoalEnd)).toBe(true);
 66	  await expect.poll(() => shipsOnCanvas(page)).toEqual([self]);
 67	
 68	  await attachScreenshot(page, testInfo, "sail-and-dock");
 69	
 70	  // Any throttle casts off.
 71	  await page.keyboard.down("ArrowDown");
 72	  await expect(page.getByTestId("hud-dock")).toHaveText("at sea");
 73	  await page.keyboard.up("ArrowDown");
 74	});
