 76	test("ships out of sight are neither listed nor drawn until one sails within sight [scenario:out-of-sight]", async ({ browser, request }, testInfo) => {
 77	  const hostContext = await browser.newContext();
 78	  const guestContext = await browser.newContext();
 79	  try {
 80	    const host = await hostContext.newPage();
