  1	import { matchMaker } from "colyseus";
  2	import { afterAll, afterEach, beforeAll, describe, expect, it } from "vitest";
  3	import { SIGHT_RADIUS_TILES, SUB_UNITS_PER_TILE } from "@pirate-sea-race/content";
  4	import { MatchRoom, startGameServer, type RunningGameServer } from "@pirate-sea-race/server";
  5	import { AHEAD, HeadlessClient, sleep, type ShipView } from "@pirate-sea-race/test-tools";
  6	
  7	/**
  8	 * Server-enforced visibility (§3, §16) on real clients: what each headless client decodes, and the raw bytes it
  9	 * received, hold its own ship and the ships inside its sight radius, and nothing else.
 10	 */
 11	let server: RunningGameServer;
 12	let endpoint: string;
 13	const clients: HeadlessClient[] = [];
 14	const SIGHT = SIGHT_RADIUS_TILES * SUB_UNITS_PER_TILE;
 15	const OPEN_ROW = 76;
 16	
 17	async function track(client: Promise<HeadlessClient>): Promise<HeadlessClient> {
 18	  const joined = await client;
 19	  clients.push(joined);
 20	  return joined;
 21	}
 22	
 23	beforeAll(async () => {
 24	  server = await startGameServer({ port: 0, host: "127.0.0.1", handleSignals: false, testPlacement: true });
 25	  endpoint = `http://127.0.0.1:${server.port}`;
 26	});
 27	
 28	afterEach(async () => {
 29	  await Promise.all(clients.splice(0).map((client) => client.leave()));
 30	});
 31	
 32	afterAll(async () => {
 33	  await server.close();
 34	});
 35	
 36	function distance(a: ShipView, b: ShipView): number {
 37	  return Math.hypot(a.x - b.x, a.y - b.y);
 38	}
 39	
 40	function containsText(frame: Uint8Array, text: string): boolean {
 41	  return Buffer.from(frame).includes(Buffer.from(text, "utf8"));
 42	}
 43	
 44	/** Two players in one match, placed on the open row `apartTiles` apart; the guest faces the host. */
 45	async function pairApart(apartTiles: number): Promise<{ host: HeadlessClient; guest: HeadlessClient }> {
 46	  const host = await track(HeadlessClient.create(endpoint));
 47	  const guest = await track(HeadlessClient.join(endpoint, host.code));
 48	  await host.waitFor(() => host.playerCount === 2);
 49	  await host.placeShip(endpoint, { tileX: 100, tileY: OPEN_ROW, heading: 0 });
 50	  await guest.placeShip(endpoint, { tileX: 100 + apartTiles, tileY: OPEN_ROW, heading: 32 });
 51	  return { host, guest };
 52	}
 53	
 54	describe("sight radius", () => {
 55	  it("keeps a ship out of sight out of the other client's state and payload until it sails within the radius, and drops it when it leaves", async () => {
 56	    const { host, guest } = await pairApart(2 * SIGHT_RADIUS_TILES);
 57	    const hostShip = host.ship()!;
 58	    await sleep(300);
 59	
 60	    // Out of sight: each client decodes only its own ship, both know there are two players, and the room's views
 61	    // agree.
 62	    expect(guest.visibleShipIds()).toEqual([guest.sessionId]);
 63	    expect(host.visibleShipIds()).toEqual([host.sessionId]);
 64	    expect(guest.playerCount).toBe(2);
 65	    const room = matchMaker.getLocalRoomById(host.room.roomId) as unknown as MatchRoom;
 66	    expect(room.viewedShipIds(guest.sessionId)).toEqual([guest.sessionId]);
 67	
 68	    // The guest sails toward the host. Until the host is in its state, it is out of range; once it is, it is in range.
 69	    let wasHidden = false;
 70	    await guest.holdUntil(AHEAD, () => {
 71	      const ownShip = guest.ship()!;
 72	      const seen = guest.ship(host.sessionId);
 73	      if (seen === undefined) {
 74	        expect(distance(ownShip, hostShip)).toBeGreaterThan(SIGHT - 3 * 64);
 75	        wasHidden = true;
 76	        return false;
 77	      }
 78	      expect(distance(ownShip, seen)).toBeLessThanOrEqual(SIGHT);
 79	      return true;
 80	    });
 81	    expect(wasHidden).toBe(true);
 82	    expect(guest.ship(host.sessionId)).toEqual(hostShip);
 83	    // Sight is mutual: the host now sees the guest too.
 84	    await host.waitFor(() => host.ship(guest.sessionId) !== undefined);
 85	
 86	    // Every frame the guest received while the host was hidden, including the join's full state, never named the
 87	    // host's ship: its id first crosses the network in the patch that reveals it.
 88	    const guestFrames = guest.framesSince(0);
 89	    const firstMention = guestFrames.findIndex((frame) => containsText(frame, host.sessionId));
 90	    expect(firstMention).toBeGreaterThan(0);
 91	    expect(guestFrames.slice(0, firstMention).some((frame) => containsText(frame, guest.sessionId))).toBe(true);
 92	
 93	    // The guest backs away (brake, then slow reverse) until the host drops out of its state again.
 94	    await guest.holdUntil({ moveX: 0, moveY: 1 }, () => guest.ship(host.sessionId) === undefined, 15_000);
 95	    expect(distance(guest.ship()!, hostShip)).toBeGreaterThan(SIGHT);
 96	    await host.waitFor(() => host.ship(guest.sessionId) === undefined);
 97	    // Its own ship never leaves a client's state.
 98	    expect(guest.visibleShipIds()).toEqual([guest.sessionId]);
 99	    expect(host.visibleShipIds()).toEqual([host.sessionId]);
100	
101	    // Once hidden again, the host's changes no longer reach the guest: it backs away west, further out of sight.
102	    const mark = guest.frameCount;
103	    const before = host.ship()!;
104	    await host.hold({ moveX: 0, moveY: 1 }, 500);
105	    await host.waitFor(() => host.ship()!.x < before.x);
106	    await sleep(200);
107	    expect(guest.framesSince(mark).length).toBeGreaterThan(0);
108	    expect(guest.framesSince(mark).some((frame) => containsText(frame, host.sessionId))).toBe(false);
109	    expect(guest.ship(host.sessionId)).toBeUndefined();
110	  });
111	
112	  it("shows each client exactly the ships within its own radius among several players", async () => {
113	    const host = await track(HeadlessClient.create(endpoint));
114	    const second = await track(HeadlessClient.join(endpoint, host.code));
115	    const third = await track(HeadlessClient.join(endpoint, host.code));
116	    await host.waitFor(() => host.playerCount === 3);
117	    // host at 100, second 8 tiles east (in sight of both), third 8 tiles further (in sight of second only).
118	    await host.placeShip(endpoint, { tileX: 100, tileY: OPEN_ROW, heading: 0 });
119	    await second.placeShip(endpoint, { tileX: 108, tileY: OPEN_ROW, heading: 0 });
120	    await third.placeShip(endpoint, { tileX: 116, tileY: OPEN_ROW, heading: 0 });
121	    await host.waitFor(() => host.visibleShipIds().length === 2);
122	    await second.waitFor(() => second.visibleShipIds().length === 3);
123	    await third.waitFor(() => third.visibleShipIds().length === 2);
124	    await sleep(200);
125	    expect(host.visibleShipIds()).toEqual([host.sessionId, second.sessionId].sort());
126	    expect(second.visibleShipIds()).toEqual([host.sessionId, second.sessionId, third.sessionId].sort());
127	    expect(third.visibleShipIds()).toEqual([second.sessionId, third.sessionId].sort());
128	    for (const client of [host, second, third]) expect(client.playerCount).toBe(3);
129	  });
130	});
