  1	import { expect, type APIRequestContext, type Page, type TestInfo } from "@playwright/test";
  2	import { HEADING_COUNT, SUB_UNITS_PER_TILE } from "../../packages/content/src/index.js";
  3	import { TEST_PLACEMENT_PATH } from "../../packages/protocol/src/index.js";
  4	
  5	export const SERVER_URL = "http://localhost:2593";
  6	export const TILE = SUB_UNITS_PER_TILE;
  7	const PIXELS_PER_SUB_UNIT = 16 / SUB_UNITS_PER_TILE;
  8	
  9	export interface Readout {
 10	  readonly id: string;
 11	  readonly slot: number;
 12	  readonly x: number;
 13	  readonly y: number;
 14	  readonly heading: number;
 15	  readonly speed: number;
 16	  readonly dock: number;
 17	}
 18	
 19	export interface DrawnShip {
 20	  readonly id: string;
 21	  readonly x: number;
 22	  readonly y: number;
 23	  readonly color: string;
 24	}
 25	
 26	export async function createMatch(page: Page): Promise<string> {
 27	  await page.goto("/");
 28	  await page.getByRole("button", { name: "Create match" }).click();
 29	  await expect(page.getByTestId("hud-status")).toHaveText("connected");
 30	  const code = page.getByTestId("hud-code");
 31	  await expect(code).toHaveText(/^[A-Z0-9]{6}$/);
 32	  return (await code.textContent())!;
 33	}
 34	
 35	export async function joinMatch(page: Page, code: string): Promise<void> {
 36	  await page.goto("/");
 37	  await page.getByLabel("Match code").fill(code);
 38	  await page.getByRole("button", { name: "Join" }).click();
 39	  await expect(page.getByTestId("hud-status")).toHaveText("connected");
 40	}
 41	
 42	export async function selfId(page: Page): Promise<string> {
 43	  return (await page.getByTestId("hud-self").textContent())!;
 44	}
 45	
 46	/** Every ship the page's HUD lists, with the latest decoded server state. */
 47	export async function listed(page: Page): Promise<Readout[]> {
 48	  return page.evaluate(() =>
 49	    [...document.querySelectorAll<HTMLElement>('[data-testid="positions"] [data-ship-id]')].map((item) => ({
 50	      id: item.dataset["shipId"]!,
 51	      slot: Number(item.dataset["slot"]),
 52	      x: Number(item.dataset["x"]),
 53	      y: Number(item.dataset["y"]),
 54	      heading: Number(item.dataset["heading"]),
 55	      speed: Number(item.dataset["speed"]),
 56	      dock: Number(item.dataset["dock"]),
 57	    })),
 58	  );
 59	}
 60	
 61	export async function listedIds(page: Page): Promise<string[]> {
 62	  return (await listed(page)).map((ship) => ship.id).sort();
 63	}
 64	
 65	/** A ship's authoritative state in a page's HUD, or undefined when the page does not list it. */
 66	export async function readout(page: Page, shipId: string): Promise<Readout | undefined> {
 67	  return (await listed(page)).find((ship) => ship.id === shipId);
 68	}
 69	
 70	export async function drawnShips(page: Page): Promise<DrawnShip[]> {
 71	  return JSON.parse((await page.getByTestId("game").getAttribute("data-drawn-ships")) ?? "[]") as DrawnShip[];
 72	}
 73	
 74	export async function drawnIds(page: Page): Promise<string[]> {
 75	  return (await drawnShips(page)).map((ship) => ship.id).sort();
 76	}
 77	
 78	/**
 79	 * Test-only placement (the server's PIRATE_SEA_RACE_TEST_PLACEMENT setting, on for these tests): puts a player's
 80	 * ship at rest on a tile, then waits until the page shows it there.
 81	 */
 82	export async function place(request: APIRequestContext, page: Page, code: string, tileX: number, tileY: number, heading: number): Promise<void> {
 83	  const sessionId = await selfId(page);
 84	  const response = await request.post(`${SERVER_URL}${TEST_PLACEMENT_PATH}`, { data: { code, sessionId, tileX, tileY, heading } });
 85	  expect(response.status(), await response.text()).toBe(200);
 86	  await expect
 87	    .poll(async () => {
 88	      const ship = await readout(page, sessionId);
 89	      return ship === undefined ? undefined : [ship.x, ship.y, ship.speed];
 90	    })
 91	    .toEqual([tileX * TILE + TILE / 2, tileY * TILE + TILE / 2, 0]);
 92	}
 93	
 94	/** Canvas pixels as RGBA rows, read from a real screenshot of the canvas. */
 95	async function canvasPixels(page: Page, points: readonly { x: number; y: number }[], radius: number): Promise<[number, number, number][][]> {
 96	  const png = await page.locator("#game canvas").screenshot();
 97	  return page.evaluate(
 98	    async ({ base64, points, radius }) => {
 99	      const blob = await (await fetch(`data:image/png;base64,${base64}`)).blob();
100	      const bitmap = await createImageBitmap(blob);
101	      const canvas = new OffscreenCanvas(bitmap.width, bitmap.height);
102	      const context = canvas.getContext("2d")!;
103	      context.drawImage(bitmap, 0, 0);
104	      return points.map(({ x, y }) => {
105	        const pixels: [number, number, number][] = [];
106	        for (let dy = -radius; dy <= radius; dy++) {
