122	function near(pixel: [number, number, number], color: string, tolerance = 24): boolean {
123	  const want = Number.parseInt(color.slice(1), 16);
124	  const [r, g, b] = pixel;
125	  return Math.abs(r - ((want >> 16) & 0xff)) <= tolerance && Math.abs(g - ((want >> 8) & 0xff)) <= tolerance && Math.abs(b - (want & 0xff)) <= tolerance;
