132	export async function shipsOnCanvas(page: Page): Promise<string[]> {
133	  const drawn = await drawnShips(page);
134	  const pixels = await canvasPixels(page, drawn, 0);
135	  return drawn.filter((ship, index) => near(pixels[index]![0]!, ship.color)).map((ship) => ship.id).sort();
