162	/** Holds the keys of a keyboard helm, sending only changes. */
163	class Keys {
164	  private readonly down = new Set<string>();
165	
166	  constructor(private readonly page: Page) {}
167	
168	  async set(key: string, pressed: boolean): Promise<void> {
169	    if (pressed === this.down.has(key)) return;
170	    if (pressed) {
171	      await this.page.keyboard.down(key);
172	      this.down.add(key);
173	    } else {
174	      await this.page.keyboard.up(key);
175	      this.down.delete(key);
176	    }
177	  }
