184	export interface SailOptions {
185	  /** Stop once the ship is this close to the target, in sub-units. */
186	  readonly within?: number;
187	  /** Or once this holds. */
188	  readonly until?: () => Promise<boolean>;
189	  readonly timeoutMs?: number;
190	  /** Called with every readout on the way, for checks along the route. */
191	  readonly onReadout?: (ship: Readout) => void;
192	}
193	
194	/**
195	 * Sails a page's ship toward a world position with the keyboard only, steering from the HUD's authoritative readout:
196	 * left or right toward the bearing, up when roughly on course and below the wanted speed, down when too fast. The
197	 * wanted speed falls as the target nears, so the ship arrives slowly.
198	 */
199	export async function sailTo(page: Page, target: { x: number; y: number }, options: SailOptions = {}): Promise<Readout> {
200	  const id = await selfId(page);
201	  const keys = new Keys(page);
202	  const deadline = Date.now() + (options.timeoutMs ?? 30_000);
203	  try {
204	    for (;;) {
205	      const ship = await readout(page, id);
206	      if (ship === undefined) throw new Error("own ship missing from the HUD");
207	      options.onReadout?.(ship);
208	      const dx = target.x - ship.x;
209	      const dy = target.y - ship.y;
210	      const distance = Math.hypot(dx, dy);
211	      if (options.within !== undefined && distance <= options.within) return ship;
212	      if (options.until !== undefined && (await options.until())) return ship;
213	      if (Date.now() > deadline) throw new Error(`did not reach ${target.x},${target.y} (at ${ship.x},${ship.y})`);
214	      const bearing = Math.round((Math.atan2(dy, dx) / (2 * Math.PI)) * HEADING_COUNT);
215	      const turn = ((((bearing - ship.heading) % HEADING_COUNT) + HEADING_COUNT + HEADING_COUNT / 2) % HEADING_COUNT) - HEADING_COUNT / 2;
216	      await keys.set("ArrowRight", turn > 0);
217	      await keys.set("ArrowLeft", turn < 0);
218	      const wanted = Math.min(64, Math.max(14, (distance / TILE) * 10));
219	      const onCourse = Math.abs(turn) <= 4;
220	      await keys.set("ArrowUp", onCourse && ship.speed < wanted - 2);
221	      await keys.set("ArrowDown", ship.speed > wanted + 8);
222	      await page.waitForTimeout(30);
223	    }
224	  } finally {
225	    await keys.releaseAll();
226	  }
227	}
