 1	import { expect, test } from "@playwright/test";
 2	import { PROTOCOL_VERSION } from "../../packages/protocol/src/version.js";
 3	import { attachScreenshot, createMatch, joinMatch, listedIds, place, readout, selfId, shipsOnCanvas, TILE } from "./helpers.js";
 4	
 5	/** An open stretch of sea on the slice map, clear for tens of tiles east and west. */
 6	const OPEN_ROW = 76;
 7	
 8	test("create a private match from the landing page and see it in the HUD [scenario:join-private-match]", async ({ page }, testInfo) => {
 9	  await page.goto("/");
10	  await expect(page.getByRole("heading", { name: "Pirate Sea Race" })).toBeVisible();
11	
12	  // An unknown code is refused on the landing page.
13	  await page.getByLabel("Match code").fill("zzzzz9");
14	  await page.getByRole("button", { name: "Join" }).click();
15	  await expect(page.getByTestId("join-error")).toHaveText("No match with that code");
16	
17	  await page.getByRole("button", { name: "Create match" }).click();
18	  await expect(page.getByTestId("hud-status")).toHaveText("connected");
19	  await expect(page.getByTestId("hud-code")).toHaveText(/^[A-Z0-9]{6}$/);
20	  await expect(page.getByTestId("hud-protocol")).toHaveText(`v${PROTOCOL_VERSION}`);
21	  await expect(page.getByTestId("hud-players")).toHaveText("1");
22	  await expect(page.getByTestId("hud-mode")).toHaveText("custom");
23	  await expect(page.getByTestId("hud-dock")).toHaveText("at sea");
24	  await expect(page.getByRole("button", { name: "Create match" })).toBeHidden();
25	
26	  // The player's ship is drawn on the map, and the minimap's fog has cleared around it.
27	  const self = await selfId(page);
28	  await expect.poll(() => shipsOnCanvas(page)).toEqual([self]);
29	  expect(Number(await page.getByTestId("game").getAttribute("data-fog-revealed"))).toBeGreaterThan(100);
30	
31	  await attachScreenshot(page, testInfo, "join-private-match");
32	});
