34	test("a ship sailed in one browser moves in the other, in sight of it [scenario:two-ships-sync]", async ({ browser, request }, testInfo) => {
35	  const hostContext = await browser.newContext();
36	  const guestContext = await browser.newContext();
37	  try {
38	    const host = await hostContext.newPage();
39	    const guest = await guestContext.newPage();
40	
41	    const code = await createMatch(host);
42	    await joinMatch(guest, code.toLowerCase());
