     1	import * as Phaser from "phaser";
     2	import { HEADING_COUNT, insideIsland, ISLAND_THEMES, SIGHT_RADIUS_TILES, Terrain, terrainAt, type IslandTheme } from "@pirate-sea-race/content";
     3	import { defaultSimulationConfig } from "@pirate-sea-race/simulation";
     4	import { followScroll, TILE_PIXELS, VIEW_HEIGHT, VIEW_WIDTH } from "./camera.js";
     5	import { FogOfWar } from "./fog.js";
     6	import { cssColor, slotColor, type MatchView } from "./matchView.js";
     7	
     8	const { map } = defaultSimulationConfig;
     9	const WORLD_WIDTH = map.widthTiles * TILE_PIXELS;
    10	const WORLD_HEIGHT = map.heightTiles * TILE_PIXELS;
    11	const PIXELS_PER_SUB_UNIT = TILE_PIXELS / map.subUnitsPerTile;
    12	
    13	/** Placeholder palette. None of these is near a ship colour, so a ship's colour on the canvas is always a ship. */
    14	const SEA_COLOR = 0x0b3d5c;
    15	const GRID_COLOR = 0x145374;
    16	const SHOAL_COLOR = 0x2e7d86;
    17	const SHOAL_FLECK = 0x4f9aa0;
    18	const DOCK_COLOR = 0x8b5a2b;
    19	const DOCK_PLANK = 0x6b4220;
    20	const LAND_COLORS: Readonly<Record<IslandTheme, number>> = { tropical: 0x6b8e23, volcanic: 0x5b4a45, ruin: 0x9a8f73, mist: 0x7d8a99 };
    21	const FOG_COLOR = 0x16202a;
    22	const OWN_RING_COLOR = 0xfff3b0;
    23	const SIGHT_COLOR = 0x9bd1e5;
    24	
    25	/** Tile indexes in the generated tileset texture. */
    26	const TILE_SEA = 0;
    27	const TILE_SHOAL = 1;
    28	const TILE_DOCK = 2;
    29	const TILE_LAND = 3;
    30	
    31	const MINIMAP_SCALE = 0.75;
    32	const MINIMAP_MARGIN = 8;
    33	
    34	/** A ship as drawn this frame, in canvas pixels, for the DOM report tests read. */
    35	export interface DrawnShip {
    36	  readonly id: string;
    37	  readonly x: number;
    38	  readonly y: number;
    39	  readonly color: string;
    40	}
    41	
    42	function landTile(tileX: number, tileY: number): number {
    43	  const theme = map.islands.find((island) => insideIsland(island, tileX, tileY))?.theme ?? "tropical";
    44	  return TILE_LAND + ISLAND_THEMES.indexOf(theme);
    45	}
    46	
    47	function tileIndex(tileX: number, tileY: number): number {
    48	  switch (terrainAt(map, tileX, tileY)) {
    49	    case Terrain.Land:
    50	      return landTile(tileX, tileY);
    51	    case Terrain.Shoal:
    52	      return TILE_SHOAL;
    53	    case Terrain.Dock:
    54	      return TILE_DOCK;
    55	    default:
    56	      return TILE_SEA;
    57	  }
    58	}
    59	
    60	function tileColor(tileX: number, tileY: number): number {
    61	  const index = tileIndex(tileX, tileY);
    62	  if (index >= TILE_LAND) return LAND_COLORS[ISLAND_THEMES[index - TILE_LAND]!];
    63	  return [SEA_COLOR, SHOAL_COLOR, DOCK_COLOR][index]!;
    64	}
    65	
    66	/**
    67	 * Draws the sea: the tile map from content, the ships the server sent at interpolated positions, a camera that
    68	 * follows the player's ship, the sight circle, and a minimap whose fog clears along the player's path. Each frame
    69	 * it records what it drew in data attributes on the report element (`data-drawn-ships`, `data-camera`,
    70	 * `data-fog-revealed`) for the browser tests.
    71	 */
    72	export class SeaScene extends Phaser.Scene {
    73	  private readonly shipGraphics = new Map<string, Phaser.GameObjects.Graphics>();
    74	  private readonly fog = new FogOfWar(map.widthTiles, map.heightTiles, SIGHT_RADIUS_TILES);
    75	  private minimap!: Phaser.Textures.CanvasTexture;
    76	  private minimapMarks!: Phaser.GameObjects.Graphics;
    77	  private sight!: Phaser.GameObjects.Graphics;
    78	  private lastReport = "";
    79	
    80	  constructor(
    81	    private readonly view: MatchView,
    82	    private readonly report: HTMLElement,
    83	  ) {
    84	    super("sea");
    85	  }
    86	
    87	  create(): void {
    88	    this.createTerrain();
    89	    this.sight = this.add.graphics();
    90	    this.sight.lineStyle(1, SIGHT_COLOR, 0.45);
    91	    this.sight.strokeCircle(0, 0, SIGHT_RADIUS_TILES * TILE_PIXELS);
    92	    this.sight.setDepth(1);
    93	    this.createMinimap();
    94	  }
    95	
    96	  /** The tile map, as a Phaser tilemap over a tileset texture drawn here in placeholder colours. */
    97	  private createTerrain(): void {
    98	    const kinds = TILE_LAND + ISLAND_THEMES.length;
    99	    const tileset = this.textures.createCanvas("terrain-tiles", kinds * TILE_PIXELS, TILE_PIXELS)!;
   100	    const context = tileset.getContext();
   101	    const paint = (index: number, color: number) => {
   102	      context.fillStyle = cssColor(color);
   103	      context.fillRect(index * TILE_PIXELS, 0, TILE_PIXELS, TILE_PIXELS);
   104	    };
   105	    paint(TILE_SEA, SEA_COLOR);
   106	    paint(TILE_SHOAL, SHOAL_COLOR);
   107	    context.fillStyle = cssColor(SHOAL_FLECK);
   108	    for (const [x, y] of [[3, 4], [10, 2], [6, 10], [13, 12], [2, 13]] as const) context.fillRect(TILE_SHOAL * TILE_PIXELS + x, y, 2, 2);
   109	    paint(TILE_DOCK, DOCK_COLOR);
   110	    context.fillStyle = cssColor(DOCK_PLANK);
   111	    for (const y of [4, 9, 14]) context.fillRect(TILE_DOCK * TILE_PIXELS, y, TILE_PIXELS, 1);
   112	    ISLAND_THEMES.forEach((theme, index) => paint(TILE_LAND + index, LAND_COLORS[theme]));
   113	    tileset.refresh();
   114	
   115	    // Open sea is left empty (-1): the camera's background is the sea, so the layer draws only the few land, shoal
   116	    // and dock tiles in view. Drawing every sea tile too costs a software renderer most of its frame rate.
   117	    const data = Array.from({ length: map.heightTiles }, (_, tileY) =>
   118	      Array.from({ length: map.widthTiles }, (_, tileX) => {
   119	        const index = tileIndex(tileX, tileY);
   120	        return index === TILE_SEA ? -1 : index;
   121	      }),
   122	    );
   123	    const tilemap = this.make.tilemap({ data, tileWidth: TILE_PIXELS, tileHeight: TILE_PIXELS });
   124	    const tiles = tilemap.addTilesetImage("terrain", "terrain-tiles", TILE_PIXELS, TILE_PIXELS, 0, 0)!;
   125	    tilemap.createLayer(0, tiles, 0, 0);
   126	
   127	    // A chart grid every eight tiles, so open water shows the ship's motion.
   128	    const grid = this.add.graphics();
   129	    grid.lineStyle(1, GRID_COLOR, 0.6);
   130	    for (let tile = 0; tile <= map.widthTiles; tile += 8) grid.lineBetween(tile * TILE_PIXELS, 0, tile * TILE_PIXELS, WORLD_HEIGHT);
   131	    for (let tile = 0; tile <= map.heightTiles; tile += 8) grid.lineBetween(0, tile * TILE_PIXELS, WORLD_WIDTH, tile * TILE_PIXELS);
   132	
   133	    for (const island of map.islands) {
   134	      const label = this.add.text((island.tileX + island.widthTiles / 2) * TILE_PIXELS, (island.tileY - 1.2) * TILE_PIXELS, island.name, {
   135	        fontFamily: "system-ui, sans-serif",
   136	        fontSize: "12px",
   137	        color: "#e8f1f5",
   138	      });
   139	      label.setOrigin(0.5, 0.5).setAlpha(0.85);
   140	    }
   141	  }
   142	
   143	  /** The minimap: one pixel per tile, fogged until the player's ship has seen it. */
   144	  private createMinimap(): void {
   145	    this.minimap = this.textures.createCanvas("minimap", map.widthTiles, map.heightTiles)!;
   146	    const context = this.minimap.getContext();
   147	    context.fillStyle = cssColor(FOG_COLOR);
   148	    context.fillRect(0, 0, map.widthTiles, map.heightTiles);
   149	    this.minimap.refresh();
   150	    const left = VIEW_WIDTH - MINIMAP_MARGIN - map.widthTiles * MINIMAP_SCALE;
   151	    const frame = this.add.graphics().setScrollFactor(0).setDepth(10);
   152	    frame.lineStyle(2, 0x9bb8c6, 0.9);
   153	    frame.strokeRect(left - 1, MINIMAP_MARGIN - 1, map.widthTiles * MINIMAP_SCALE + 2, map.heightTiles * MINIMAP_SCALE + 2);
   154	    this.add.image(left, MINIMAP_MARGIN, "minimap").setOrigin(0, 0).setScale(MINIMAP_SCALE).setScrollFactor(0).setDepth(10);
   155	    this.minimapMarks = this.add.graphics().setScrollFactor(0).setDepth(11);
   156	  }
   157	
   158	  private revealFog(x: number, y: number): void {
   159	    const fresh = this.fog.revealAround(Math.floor(x / TILE_PIXELS), Math.floor(y / TILE_PIXELS));
   160	    if (fresh.length === 0) return;
   161	    const context = this.minimap.getContext();
   162	    for (const [tileX, tileY] of fresh) {
   163	      context.fillStyle = cssColor(tileColor(tileX, tileY));
   164	      context.fillRect(tileX, tileY, 1, 1);
   165	    }
   166	    this.minimap.refresh();
   167	    this.report.dataset["fogRevealed"] = String(this.fog.revealedCount);
   168	  }
   169	
   170	  override update(): void {
   171	    const now = performance.now();
   172	    const own = this.view.renderPosition(this.view.selfId, now);
   173	    if (own !== undefined) {
   174	      const x = own.x * PIXELS_PER_SUB_UNIT;
   175	      const y = own.y * PIXELS_PER_SUB_UNIT;
   176	      const scroll = followScroll(x, y);
   177	      this.cameras.main.setScroll(scroll.x, scroll.y);
   178	      this.sight.setPosition(x, y);
   179	      this.revealFog(x, y);
   180	    }
   181	    const camera = this.cameras.main;
   182	    const minimapLeft = VIEW_WIDTH - MINIMAP_MARGIN - map.widthTiles * MINIMAP_SCALE;
   183	    this.minimapMarks.clear();
   184	
   185	    const drawn: DrawnShip[] = [];
   186	    const present = new Set<string>();
   187	    for (const ship of this.view.ships()) {
   188	      const position = this.view.renderPosition(ship.id, now);
   189	      if (position === undefined) continue;
   190	      present.add(ship.id);
   191	      const mine = ship.id === this.view.selfId;
   192	      let graphics = this.shipGraphics.get(ship.id);
   193	      if (graphics === undefined) {
   194	        graphics = this.drawShip(slotColor(ship.slot), mine);
   195	        this.shipGraphics.set(ship.id, graphics);
   196	      }
   197	      const x = position.x * PIXELS_PER_SUB_UNIT;
   198	      const y = position.y * PIXELS_PER_SUB_UNIT;
   199	      graphics.setPosition(x, y);
   200	      graphics.setRotation((ship.heading * 2 * Math.PI) / HEADING_COUNT);
   201	      drawn.push({ id: ship.id, x: Math.round(x - camera.scrollX), y: Math.round(y - camera.scrollY), color: cssColor(slotColor(ship.slot)) });
   202	      this.minimapMarks.fillStyle(mine ? OWN_RING_COLOR : slotColor(ship.slot), 1);
   203	      this.minimapMarks.fillRect(minimapLeft + (x / TILE_PIXELS) * MINIMAP_SCALE - 1.5, MINIMAP_MARGIN + (y / TILE_PIXELS) * MINIMAP_SCALE - 1.5, 3, 3);
   204	    }
   205	    for (const [id, graphics] of this.shipGraphics) {
   206	      if (present.has(id)) continue;
   207	      graphics.destroy();
   208	      this.shipGraphics.delete(id);
   209	    }
   210	    const report = JSON.stringify(drawn);
   211	    if (report !== this.lastReport) {
   212	      this.report.dataset["drawnShips"] = report;
   213	      this.lastReport = report;
   214	    }
   215	    this.report.dataset["camera"] = `${camera.scrollX},${camera.scrollY}`;
   216	  }
   217	
   218	  /** A round hull with a bow pointing along +x; the player's own ship gets a pale ring. */
   219	  private drawShip(color: number, own: boolean): Phaser.GameObjects.Graphics {
   220	    const graphics = this.add.graphics();
   221	    graphics.setDepth(2);
   222	    graphics.fillStyle(color, 1);
   223	    graphics.fillCircle(0, 0, 6);
   224	    graphics.fillTriangle(3, -5, 12, 0, 3, 5);
   225	    if (own) {
   226	      graphics.lineStyle(2, OWN_RING_COLOR, 1);
   227	      graphics.strokeCircle(0, 0, 10);
   228	    }
   229	    return graphics;
   230	  }
   231	}
   232	
   233	export function startGame(parent: HTMLElement, view: MatchView): Phaser.Game {
   234	  return new Phaser.Game({
   235	    type: Phaser.AUTO,
   236	    parent,
   237	    width: VIEW_WIDTH,
   238	    height: VIEW_HEIGHT,
   239	    backgroundColor: SEA_COLOR,
   240	    banner: false,
   241	    audio: { noAudio: true },
   242	    scene: new SeaScene(view, parent),
   243	  });
   244	}
     1	/**
     2	 * The minimap's fog (§3): every tile starts hidden, and tiles within the sight radius of the player's ship are
     3	 * revealed for good as it sails. Terrain is public content, so this is presentation only, not a security boundary
     4	 * (§16); ships are filtered by the server.
     5	 */
     6	export class FogOfWar {
     7	  private readonly revealed: Uint8Array;
     8	  private count = 0;
     9	  private lastTile = -1;
    10	
    11	  constructor(
    12	    readonly widthTiles: number,
    13	    readonly heightTiles: number,
    14	    readonly radiusTiles: number,
    15	  ) {
    16	    this.revealed = new Uint8Array(widthTiles * heightTiles);
    17	  }
    18	
    19	  get revealedCount(): number {
    20	    return this.count;
    21	  }
    22	
    23	  isRevealed(tileX: number, tileY: number): boolean {
    24	    return this.revealed[tileY * this.widthTiles + tileX] === 1;
    25	  }
    26	
    27	  /** Reveals the disc around a tile and returns the tiles it newly revealed, as `[tileX, tileY]` pairs. */
    28	  revealAround(tileX: number, tileY: number): [number, number][] {
    29	    const centre = tileY * this.widthTiles + tileX;
    30	    if (centre === this.lastTile) return [];
    31	    this.lastTile = centre;
    32	    const fresh: [number, number][] = [];
    33	    const radius = this.radiusTiles;
    34	    for (let dy = -radius; dy <= radius; dy++) {
    35	      for (let dx = -radius; dx <= radius; dx++) {
    36	        if (dx * dx + dy * dy > radius * radius) continue;
    37	        const x = tileX + dx;
    38	        const y = tileY + dy;
    39	        if (x < 0 || y < 0 || x >= this.widthTiles || y >= this.heightTiles) continue;
    40	        const index = y * this.widthTiles + x;
    41	        if (this.revealed[index] === 1) continue;
    42	        this.revealed[index] = 1;
    43	        this.count++;
    44	        fresh.push([x, y]);
    45	      }
    46	    }
    47	    return fresh;
    48	  }
    49	}
