     6	export class FogOfWar {
     7	  private readonly revealed: Uint8Array;
     8	  private count = 0;
     9	  private lastTile = -1;
    10	
    11	  constructor(
    12	    readonly widthTiles: number,
    13	    readonly heightTiles: number,
    14	    readonly radiusTiles: number,
    15	  ) {
    16	    this.revealed = new Uint8Array(widthTiles * heightTiles);
    17	  }
    18	
    19	  get revealedCount(): number {
    20	    return this.count;
    21	  }
    22	
    23	  isRevealed(tileX: number, tileY: number): boolean {
    24	    return this.revealed[tileY * this.widthTiles + tileX] === 1;
    25	  }
    26	
    27	  /** Reveals the disc around a tile and returns the tiles it newly revealed, as `[tileX, tileY]` pairs. */
    28	  revealAround(tileX: number, tileY: number): [number, number][] {
    29	    const centre = tileY * this.widthTiles + tileX;
    30	    if (centre === this.lastTile) return [];
    31	    this.lastTile = centre;
    32	    const fresh: [number, number][] = [];
    33	    const radius = this.radiusTiles;
    34	    for (let dy = -radius; dy <= radius; dy++) {
    35	      for (let dx = -radius; dx <= radius; dx++) {
    36	        if (dx * dx + dy * dy > radius * radius) continue;
    37	        const x = tileX + dx;
    38	        const y = tileY + dy;
    39	        if (x < 0 || y < 0 || x >= this.widthTiles || y >= this.heightTiles) continue;
    40	        const index = y * this.widthTiles + x;
    41	        if (this.revealed[index] === 1) continue;
    42	        this.revealed[index] = 1;
    43	        this.count++;
    44	        fresh.push([x, y]);
    45	      }
    46	    }
    47	    return fresh;
    48	  }
    49	}
