import { describe, expect, it } from "vitest";
import tiledSource from "../../../assets/source/maps/slice-sea.tmj?raw";
import generatedModule from "./maps/sliceSea.ts?raw";
import { sliceSeaSource } from "./maps/sliceSea.js";
import { privateMatch, rulesPresets } from "./rules.js";
import { ENGAGEMENT_RANGE_TILES, shipTuning, SIGHT_RADIUS_TILES, travelTargets } from "./sailing.js";
import { seaMap, spawnSlots } from "./sea.js";
import { createSeaMap, dockLabel, insideIsland, Terrain, terrainAt, type SeaMapSource } from "./seaMap.js";
import { seaPathCosts, validateSeaMap } from "./seaValidation.js";
import { convertTiledMap, formatSeaMapModule, type TiledMap } from "./tiledMap.js";

const SOURCE_PATH = "assets/source/maps/slice-sea.tmj";

describe("map pipeline", () => {
  it("keeps the generated module in step with the Tiled source map (run `npm run map:build` after editing it)", () => {
    const converted = convertTiledMap("slice-sea", JSON.parse(tiledSource));
    if (!converted.ok) throw new Error(converted.issues.join("\n"));
    expect(converted.value).toEqual(sliceSeaSource);
    expect(formatSeaMapModule(converted.value, "sliceSeaSource", SOURCE_PATH)).toBe(generatedModule);
  });

  const tiled = (): TiledMap => JSON.parse(tiledSource) as TiledMap;
  const issuesOf = (candidate: unknown) => {
    const result = convertTiledMap("broken", candidate);
    return result.ok ? [] : result.issues;
  };

  it("refuses maps outside the documented Tiled subset", () => {
    const infinite = { ...tiled(), infinite: true };
    const extraLayer = { ...tiled(), layers: [...tiled().layers, { type: "imagelayer", name: "art" }] };
    const bigTiles = { ...tiled(), tilewidth: 32 };
    for (const broken of [infinite, extraLayer, bigTiles, "not a map"]) expect(issuesOf(broken).length).toBeGreaterThan(0);
  });

  it("refuses an empty cell, a tile without a terrain type, and flipped tiles", () => {
    for (const gid of [0, 9, 0x80000002]) {
      const map = tiled();
      map.layers[0].data[5] = gid;
      expect(issuesOf(map).length).toBeGreaterThan(0);
    }
  });

  it("refuses badly authored objects", () => {
    const edit = (change: (objects: TiledMap["layers"][1]["objects"]) => void) => {
      const map = tiled();
      change(map.layers[1].objects);
      return issuesOf(map);
    };
    const island = (objects: TiledMap["layers"][1]["objects"]) => objects.find((object) => object.type === "island")!;
    const spawn = (objects: TiledMap["layers"][1]["objects"]) => objects.find((object) => object.type === "spawn")!;
    expect(edit((objects) => void (island(objects).x += 3))).toEqual([expect.stringMatching(/tile boundaries/)]);
    expect(edit((objects) => void (island(objects).properties = [{ name: "theme", type: "string", value: "candy" }]))).toEqual([
      expect.stringMatching(/theme must be one of/),
    ]);
    expect(edit((objects) => void spawn(objects).properties!.push({ name: "loot", type: "int", value: 3 }))).toEqual([
      expect.stringMatching(/unknown property "loot"/),
    ]);
    expect(edit((objects) => void (spawn(objects).properties = [{ name: "slot", type: "int", value: 0 }]))).toEqual([
      expect.stringMatching(/facing must be one of/),
    ]);
import { readdirSync, readFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";

/**
 * The authoritative packages stay pure (CLAUDE.md, §17): no Phaser, Colyseus, DOM, timers, wall-clock time or
 * Math.random, so the same match can be simulated headlessly and identically on client and server. Nor do they call
 * floating-point transcendental functions, whose results may differ between JavaScript engines (skeleton decision:
 * integer maths only, so `hashState` is engine-independent).
 */
const root = join(dirname(fileURLToPath(import.meta.url)), "../..");
const PURE_PACKAGES = ["packages/simulation", "packages/protocol", "packages/content"];

const FORBIDDEN_MODULES: readonly RegExp[] = [
  /^phaser(\/|$)/,
  /^colyseus(\/|$)/,
  /^@colyseus\//,
  /^(node:)?timers(\/|$)/,
  /^(node:)?perf_hooks$/,
  /^(node:)?worker_threads$/,
  /^(node:)?(fs|net|http|https|dgram|child_process|os|process|crypto)(\/|$)/,
];

const FORBIDDEN_CALLS: readonly [RegExp, string][] = [
  [/\bMath\.random\b/, "Math.random"],
  [/\bDate\.now\b/, "Date.now"],
  [/\bnew Date\b/, "new Date"],
  [/\bperformance\.now\b/, "performance.now"],
  [/\bprocess\.hrtime\b/, "process.hrtime"],
  [/\b(setTimeout|setInterval|setImmediate|queueMicrotask|requestAnimationFrame)\s*\(/, "timers"],
  [/\b(window|document|navigator|localStorage|sessionStorage)\s*[.[]/, "DOM globals"],
  [/\bcrypto\.(getRandomValues|randomUUID)\b/, "crypto randomness"],
  [
    /\bMath\.(sqrt|cbrt|hypot|pow|exp|expm1|log\w*|sin|cos|tan|asin|acos|atan|atan2|sinh|cosh|tanh|asinh|acosh|atanh)\b/,
    "floating-point transcendental Math functions",
  ],
];

function sourceFiles(directory: string): string[] {
  return readdirSync(directory, { withFileTypes: true }).flatMap((entry) => {
    const path = join(directory, entry.name);
    if (entry.isDirectory()) return sourceFiles(path);
    return /\.(ts|tsx|js|mjs|cjs)$/.test(entry.name) ? [path] : [];
  });
}

/** Source without comments or string contents, so that prose mentioning a forbidden call is not a violation. */
function code(source: string): string {
  return source
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/(^|[^:])\/\/.*$/gm, "$1")
    .replace(/(["'`])(?:\\.|(?!\1)[^\\\n])*\1/g, '""');
}

function importedModules(source: string): string[] {
  const specifiers: string[] = [];
  const patterns = [
    /\bimport\s+(?:type\s+)?(?:[\w*{}\s,$]+\s+from\s+)?["']([^"']+)["']/g,
    /\bexport\s+(?:type\s+)?[\w*{}\s,$]+\s+from\s+["']([^"']+)["']/g,
import { defaultClientConditions, defaultServerConditions } from "vite";
import { defineConfig } from "vitest/config";

/** Workspace packages resolve to their TypeScript sources in tests, so nothing needs building first. */
const SOURCE_CONDITION = "@pirate-sea-race/source";

export default defineConfig({
  resolve: { conditions: [SOURCE_CONDITION, ...defaultClientConditions] },
  ssr: { resolve: { conditions: [SOURCE_CONDITION, ...defaultServerConditions] } },
  test: {
    // The summary reporter prints totals in the form the workflow verifier reads as test evidence.
    reporters: ["default", "./tests/reporters/testSummary.ts"],
    projects: [
      {
        extends: true,
        test: {
          name: "unit",
          environment: "node",
          include: ["packages/*/src/**/*.test.ts", "apps/*/src/**/*.test.ts", "tests/unit/**/*.test.ts"],
        },
      },
      {
        extends: true,
        test: {
          name: "integration",
          environment: "node",
          include: ["tests/integration/**/*.test.ts"],
          testTimeout: 20_000,
          hookTimeout: 20_000,
          // One Colyseus matchmaker per process: run the files one after another.
          fileParallelism: false,
        },
      },
    ],
  },
});

