import { defaultSimulationConfig } from "@pirate-sea-race/simulation";

const { map } = defaultSimulationConfig;
export const TILE_PIXELS = 16;
/** The canvas; the map is larger, so the camera follows the player's ship. */
export const VIEW_WIDTH = 800;
export const VIEW_HEIGHT = 560;

/** The camera's top-left corner, in whole pixels, that centres a point, kept inside the map. */
export function followScroll(centreX: number, centreY: number): { x: number; y: number } {
  const clamp = (value: number, max: number) => Math.max(0, Math.min(max, Math.round(value)));
  return {
    x: clamp(centreX - VIEW_WIDTH / 2, map.widthTiles * TILE_PIXELS - VIEW_WIDTH),
    y: clamp(centreY - VIEW_HEIGHT / 2, map.heightTiles * TILE_PIXELS - VIEW_HEIGHT),
  };
}
describe("determinism", () => {
  it("gives the same hash for the same initial state and input log after 600 steps", () => {
    const first = run(matchWithShips(1234, ["a", "b", "c"]), inputLog, 600);
    const second = run(matchWithShips(1234, ["a", "b", "c"]), inputLog, 600);
    expect(first.frame).toBe(600);
    expect(hashState(first)).toBe(hashState(second));
    expect(first).toEqual(second);
  });

  it("gives a different hash when one input changes", () => {
    const changed = inputLog.map((entry, index) => (index === 1 ? { ...entry, input: helm(-1, 1) } : entry));
    const original = run(matchWithShips(1234, ["a", "b", "c"]), inputLog, 600);
    const altered = run(matchWithShips(1234, ["a", "b", "c"]), changed, 600);
    expect(hashState(altered)).not.toBe(hashState(original));
  });

  it("hashes the complete state, including the generator and the dock", () => {
    const state = matchWithShips(1, ["a"]);
    expect(hashState({ ...state, rng: state.rng + 1 })).not.toBe(hashState(state));
    expect(hashState({ ...state, frame: 1 })).not.toBe(hashState(state));
    const docked = { ...state, ships: state.ships.map((ship) => ({ ...ship, dock: 0 })) };
    expect(hashState(docked)).not.toBe(hashState(state));
  });

  it("does not depend on key order", () => {
    const state = matchWithShips(99, ["a", "b"]);
  it("keeps eight sailing ships with per-client views inside the 60 Hz step budget", async () => {
    const host = await track(HeadlessClient.create(endpoint));
    for (let index = 0; index < 7; index++) await track(HeadlessClient.join(endpoint, host.code));
    await host.waitFor(() => host.playerCount === 8);
    // All eight in one cluster, so every view holds every ship and changes as they sail.
    await Promise.all(clients.map((client, index) => client.placeShip(endpoint, { tileX: 90 + 2 * index, tileY: OPEN_ROW, heading: 8 * index })));
